//! Word frequency tables (FrequencyWords 2018, OpenSubtitles, CC BY-SA 4.0; UNIM English words, MIT).
//!
//! The tables are sorted `word\tcount` text generated by build.rs and searched in place: nothing
//! is parsed or allocated at run time, and the data stays in the read-only image that all processes
//! loading hanfix-ime share.

/// English words: FrequencyWords counts, spelling-dictionary words with count 0.
const EN: &str = include_str!(concat!(env!("OUT_DIR"), "/en_sorted.txt"));
const KO: &str = include_str!(concat!(env!("OUT_DIR"), "/ko_sorted.txt"));
/// Spelling dictionary words (count column is always 1).
const EN_DICT: &str = include_str!(concat!(env!("OUT_DIR"), "/en_dict.txt"));
/// Corpus count of every Hangul syllable (sum over the Korean words containing it).
const SYLLABLES: &str = include_str!(concat!(env!("OUT_DIR"), "/syllables.txt"));

/// Particles and endings stripped to find a known stem (`사과를` -> `사과`). Longest first.
pub const KO_TAILS: [&str; 40] = [
    "입니다", "습니다", "이에요", "에서는", "으로는", "이라고", "에게서", "한테서", "께서는", "이랑", "에서",
    "에게", "한테", "까지", "부터", "처럼", "보다", "으로", "이다", "예요", "께서", "라고", "하고", "에는",
    "은", "는", "이", "가", "을", "를", "에", "의", "도", "로", "와", "과", "만", "요", "랑", "야",
];

/// Byte offset of the first line whose key is `>= key` (lines sorted by key bytes).
fn lower_bound(table: &str, key: &str) -> usize {
    let bytes = table.as_bytes();
    let (mut lo, mut hi) = (0usize, bytes.len());
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        // Start of the line containing `mid` ('\n' never occurs inside a UTF-8 sequence).
        let start = bytes[..mid].iter().rposition(|&b| b == b'\n').map_or(0, |i| i + 1);
        let end = bytes[start..].iter().position(|&b| b == b'\n').map_or(bytes.len(), |i| start + i);
        let line_key = table[start..end].split('\t').next().unwrap_or("");
        if line_key < key {
            lo = end + 1;
        } else {
            hi = start;
        }
    }
    lo.min(bytes.len())
}

/// The `(key, count)` line at byte offset `at`, if any.
fn line_at(table: &str, at: usize) -> Option<(&str, u64)> {
    let rest = table.get(at..)?;
    let line = rest.split('\n').next().filter(|l| !l.is_empty())?;
    let (k, v) = line.split_once('\t')?;
    Some((k, v.parse().ok()?))
}

fn lookup(table: &str, key: &str) -> Option<u64> {
    line_at(table, lower_bound(table, key)).and_then(|(k, v)| (k == key).then_some(v))
}

pub struct Lexicon;

impl Lexicon {
    pub fn get() -> &'static Lexicon {
        &Lexicon
    }

    /// Frequency count of a lowercase English word (0 if unknown or dictionary-only).
    pub fn en_count(&self, word: &str) -> u32 {
        lookup(EN, word).unwrap_or(0) as u32
    }

    /// The lowercase word is a known English word (frequency list or spelling dictionary).
    pub fn en_known(&self, word: &str) -> bool {
        lookup(EN, word).is_some()
    }

    /// The word is in the English spelling dictionary (a real word, not a name or subtitle noise).
    pub fn en_in_dictionary(&self, word: &str) -> bool {
        lookup(EN_DICT, word).is_some()
    }

    /// Some known English word (2+ letters) starts with this lowercase prefix.
    pub fn en_has_prefix(&self, prefix: &str) -> bool {
        let mut at = lower_bound(EN, prefix);
        while let Some((k, _)) = line_at(EN, at) {
            if !k.starts_with(prefix) {
                return false;
            }
            if k.len() >= 2 {
                return true;
            }
            at += k.len() + EN[at + k.len()..].find('\n').map_or(0, |i| i + 1);
        }
        false
    }

    /// Frequency count of a Korean word, falling back to its stem with a particle/ending removed.
    pub fn ko_count(&self, word: &str) -> u32 {
        if let Some(c) = lookup(KO, word) {
            return c as u32;
        }
        for tail in KO_TAILS {
            if let Some(stem) = word.strip_suffix(tail) {
                if stem.chars().count() >= 2 {
                    if let Some(c) = lookup(KO, stem) {
                        return c as u32;
                    }
                }
            }
        }
        0
    }

    /// Weakest-syllable familiarity: log10 of the total corpus count of the rarest syllable in `word`.
    /// A word made only of everyday syllables scores high even if the word itself is unlisted.
    pub fn ko_familiarity(&self, word: &str) -> f32 {
        let mut buf = [0u8; 4];
        word.chars()
            .map(|ch| (lookup(SYLLABLES, ch.encode_utf8(&mut buf)).unwrap_or(0) as f32 + 1.0).log10())
            .fold(f32::INFINITY, f32::min)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn loads_embedded_lists() {
        let lex = Lexicon::get();
        assert!(lex.en_count("hello") > 1000);
        assert!(lex.ko_count("안녕하세요") > 100);
        assert_eq!(lex.en_count("dkssud"), 0);
        assert!(lex.en_known("aardvarks"), "spelling-dictionary word");
        assert_eq!(lex.en_count("aardvarks"), 0);
    }

    #[test]
    fn strips_particles_to_known_stem() {
        let lex = Lexicon::get();
        assert!(lex.ko_count("사람을") > 0);
        assert!(lex.ko_count("학교에서") > 0);
    }

    #[test]
    fn familiarity_separates_real_from_junk() {
        let lex = Lexicon::get();
        assert!(lex.ko_familiarity("하세요") > lex.ko_familiarity("뷁쀍"));
    }

    #[test]
    fn prefixes() {
        let lex = Lexicon::get();
        assert!(lex.en_has_prefix("goth"));
        assert!(lex.en_has_prefix("aardv"));
        assert!(!lex.en_has_prefix("dkssu"));
        assert!(!lex.en_has_prefix("zzzzqx"));
    }

    #[test]
    fn edges_of_the_tables() {
        let lex = Lexicon::get();
        assert_eq!(lex.en_count(""), 0);
        assert!(!lex.en_known("zzzzzzzzzzzz"));
        assert!(!lex.en_known("\u{0}"));
        assert_eq!(lex.ko_count("힣힣힣"), 0);
    }
}
